import {listeningBank,grammarBank,conversationBank} from './content-v4.js';
import {normalize,equalAnswer} from './catalog-v4.js';
export const stages=['A0','A1','A2','B1','B2'];
export function createLearningHub({show,speak,getCourse,getBase,getLearner=()=>'guest',onResult=()=>{},onBank=()=>{},bankSize=()=>100,readPractice,writePractice,celebrate}){
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const tr=(ka,en,ru)=>({ka,en,ru})[getBase()],label=x=>typeof x==='string'?x:(x?.[getBase()]||x?.en||'');
 let stage='A0',quiz=null,conversation=null,turn=0,playTicket=0;
 const key=()=>`geolingo-practice-v3-${getLearner()}-${getBase()}-${getCourse()}`;
 const load=()=>{const supplied=readPractice?.();if(supplied)return supplied;try{return JSON.parse(localStorage.getItem(key()))||{}}catch{return {}}};
 const store=(id,value)=>{const state=load();state[id]=value;if(writePractice){writePractice(state);return}try{localStorage.setItem(key(),JSON.stringify(state))}catch{}};
 const button=(action,text,extra='')=>`<button class="ghost" data-v3="${action}" ${extra}>${text}</button>`;
 const tabs=kind=>`<div class="level-tabs hub-tabs">${stages.map(l=>`<button data-v3="${kind}-level" data-stage="${l}" class="${stage===l?'selected':''}">${l}</button>`).join('')}</div>`;
 const back=kind=>button(kind,'← '+tr('მოდულები','Modules','Модули'));
 const footer=()=>`<p class="hint">${tr('პრაქტიკა • პროგრესი ინახება ამ ბრაუზერში • საერთო XP არ იცვლება.','Practice • Progress saved in this browser • No leaderboard XP.','Практика • Прогресс сохраняется в этом браузере • Без XP для рейтинга.')}</p>`;
 function library(kind){quiz=null;const data=(kind==='listen'?listeningBank:grammarBank)[getCourse()].filter(m=>m.level===stage),state=load();show(`<div class="eyebrow">GEOLINGO LAB</div><h2>${kind==='listen'?tr('მოსმენის გზა 🎧','Listening path 🎧','Путь аудирования 🎧'):tr('გრამატიკის აკადემია 📖','Grammar academy 📖','Академия грамматики 📖')}</h2><p class="sub">${kind==='listen'?tr('5 დონე · თითო დონეში 8 მოდული. სავარჯიშოების რაოდენობა მოდულზეა მითითებული. შემდეგ მოდულს ხსნის 80%-იანი შედეგი.','5 levels · 8 modules per level. Exercise counts appear on each module. Score 80% to unlock the next module.','5 уровней · 8 модулей на уровень. Число заданий указано в модуле. Нужно 80% для открытия следующего.'):tr('წესი, ახსნა, მაგალითები, გავრცელებული შეცდომები და პრაქტიკა თითოეულ მოდულში.','Rules, explanations, examples, common mistakes and practice in every module.','Правила, объяснения, примеры, типичные ошибки и практика в каждом модуле.')}</p>${tabs(kind)}<div class="module-grid">${data.map((m,i)=>{const done=state[m.id]?.passed,locked=kind==='listen'&&i>0&&!state[data[i-1].id]?.passed&&!done,number=kind==='listen'?m.items.length:m.quiz.length;return `<button class="module-card ${done?'module-done':''}" data-v3="${kind==='listen'?'listen-open':'grammar-open'}" data-id="${m.id}" ${locked?'disabled':''}><span class="module-number">${done?'✓':locked?'🔒':String(i+1).padStart(2,'0')}</span><strong>${esc(label(m.title))}</strong><small>${number} ${tr('სავარჯიშო','exercises','заданий')} ${state[m.id]?.score!==undefined?'· '+state[m.id].score+'%':''}</small></button>`}).join('')}</div>${footer()}`,'library')}
 function listening(id){const module=listeningBank[getCourse()].find(m=>m.id===id);if(!module)return;const siblings=listeningBank[getCourse()].filter(m=>m.level===module.level),pos=siblings.indexOf(module);if(pos>0&&!load()[siblings[pos-1].id]?.passed&&!load()[id]?.passed)return;const saved=load()['draft-'+id];quiz={kind:'listen',module,index:saved?.index||0,answers:saved?.answers||[],hints:saved?.hints||[],checked:false};drawQuiz()}
 function grammar(id){const m=grammarBank[getCourse()].find(m=>m.id===id);if(!m)return;show(`${back('grammar')}<div class="eyebrow">${m.level} · ${tr('გრამატიკა','Grammar','Грамматика')}</div><h2>${esc(label(m.title))}</h2><div class="grammar-copy" data-learning>${esc(label(m.explanation)).split('\n').map(p=>`<p>${p}</p>`).join('')}</div><h3>${tr('წესები და ფორმები','Rules and forms','Правила и формы')}</h3>${m.rules.map(r=>`<div class="grammar-rule"><strong data-learning>${esc(r.form)}</strong><p data-learning>${esc(label(r.detail))}</p></div>`).join('')}<h3>${tr('მაგალითები','Examples','Примеры')}</h3>${m.examples.map(e=>`<div class="grammar-example"><button class="text-button" data-audio="${esc(e[getCourse()])}" aria-label="${tr('მოსმენა','Listen','Слушать')}">🔊</button><strong data-learning>${esc(e[getCourse()])}</strong><p data-learning>${esc(e[getBase()])}</p></div>`).join('')}<h3>${tr('რას მიაქციო ყურადღება','Watch out','Обрати внимание')}</h3><p class="note" data-learning>${esc(label(m.pitfalls))}</p><button class="primary" data-v3="grammar-quiz" data-id="${m.id}">${tr('ცოდნის შემოწმება →','Check understanding →','Проверить знания →')}</button>${footer()}`,'article')}
 function drawQuiz(){
 const q=quiz;if(!q)return;q.checked=false;q.hinted=false;const isListen=q.kind==='listen',item=isListen?q.module.items[q.index]:q.module.quiz[q.index],total=isListen?q.module.items.length:q.module.quiz.length;
 if(q.index>=total)return finishQuiz();
 show(`<div class="modal-top">${back(q.kind)}<div class="bar"><div style="width:${q.index/total*100}%"></div></div><span>${q.index+1}/${total}</span></div><div class="exercise-heading"><span class="guide-orb">${isListen?'🎧':'✦'}</span><h2 class="lesson-title">${isListen?tr('მოუსმინე და ჩაწერე','Listen and type','Послушай и запиши'):esc(label(item.prompt))}</h2></div>${isListen?`<div class="listen-prompt"><button class="audio" data-audio="${esc(item[getCourse()])}" aria-label="${tr('მოსმენა','Listen','Слушать')}">▶</button>${button('slow','🐢 '+tr('ნელა','Slowly','Медленно'))}</div><label class="answer-label" for="hub-answer">${tr('ჩაწერე გაგონილი ფრაზა','Type the phrase you hear','Запиши услышанную фразу')}</label><input id="hub-answer" class="answer-input" autocomplete="off" autocapitalize="off" spellcheck="false" lang="${getCourse()}" placeholder="${{en:'Write in English…',ru:'Напишите по-русски…',zh:'用中文写…',es:'Escribe en español…'}[getCourse()]}"><details class="hub-reveal"><summary data-v3="listen-hint">💡 ${tr('ტექსტის ნახვა','Reveal text','Показать текст')}</summary><p data-learning>${esc(item[getCourse()])}</p><small data-learning>${esc(item[getBase()])}</small></details>`:`<div class="prompt" data-learning>${esc(item.sentence)}</div><div class="choices">${item.options.map((o,i)=>({o,i})).sort(()=>Math.random()-.5).map(({o,i})=>`<button class="choice" data-v3="grammar-answer" data-index="${i}" data-learning>${esc(o)}</button>`).join('')}</div>`}<div id="hub-feedback" role="status" aria-live="polite"></div><div class="lesson-actions"><span class="hint">${q.module.level} · ${esc(label(q.module.title))}</span><button class="primary" data-v3="quiz-check">${tr('შეამოწმე','Check','Проверить')}</button></div>`,'exercise');
 }
 function checkQuiz(){const q=quiz;if(!q||q.checked)return;const isListen=q.kind==='listen',item=isListen?q.module.items[q.index]:q.module.quiz[q.index],answer=isListen?document.querySelector('#hub-answer').value:q.selected;
 if(!answer?.trim()){document.querySelector('#hub-feedback').textContent=tr('ჯერ უპასუხე.','Answer first.','Сначала ответь.');return}
 const expected=isListen?item[getCourse()]:item.answer,correct=equalAnswer(answer,expected,getCourse());onResult({id:q.module.id+'-'+q.index,correct,target:getCourse(),expected,answer,translation:isListen?{ka:item.ka,en:item.en,ru:item.ru}:Object.fromEntries(['ka','en','ru'].map(l=>[l,item.prompt[l]])),context:isListen?'':item.sentence,explanation:isListen?{ka:item.ka,en:item.en,ru:item.ru}:item.prompt,origin:isListen?'listen':'grammar'});q.checked=true;document.querySelector('#modal').classList.add(correct?'answer-right':'answer-wrong');q.answers[q.index]=correct;q.hints[q.index]=q.hinted;const feedback=document.querySelector('#hub-feedback');feedback.innerHTML=`<div class="feedback ${correct?'':'bad'}"><strong>${correct?tr('ყოჩაღ! სწორია ✦','Well done! Correct ✦','Молодец! Верно ✦'):tr('კიდევ ერთი ნაბიჯი სწავლისკენ','Another step towards learning','Ещё один шаг к знаниям')}</strong>${!correct?`<p data-learning>${esc(expected)}</p>`:''}${isListen?`<p data-learning>${esc(item[getBase()])}</p>`:''}</div>`;document.querySelectorAll('#modal .choice,#hub-answer').forEach(el=>el.disabled=true);const b=document.querySelector('[data-v3="quiz-check"]');b.dataset.v3='quiz-next';b.textContent=tr('შემდეგი →','Next →','Далее →');if(isListen)store('draft-'+q.module.id,{index:q.index+1,answers:q.answers,hints:q.hints});}
 function finishQuiz(){const q=quiz,total=q.answers.length,independent=q.answers.filter((a,i)=>a&&!q.hints[i]).length,score=Math.round(independent/total*100),passed=score>=80,old=load()[q.module.id];store(q.module.id,{score:Math.max(old?.score||0,score),passed:passed||old?.passed||false});store('draft-'+q.module.id,null);show(`<div class="result"><span class="medal">${passed?'🏆':'🌱'}</span><h2>${tr('მოდული დასრულებულია','Module complete','Модуль завершён')}</h2><div class="result-stats"><span><b>${score}%</b>${tr('დამოუკიდებლად სწორი','Correct without hints','Верно без подсказок')}</span><span><b>${independent}/${total}</b>${tr('პასუხი','answers','ответов')}</span></div><p>${passed?tr('ყოჩაღ! შემდეგი მოდული გახსნილია.','Well done! The next module is unlocked.','Молодец! Следующий модуль открыт.'):tr('შემდეგი მოდულისთვის საჭიროა 80% მინიშნების გარეშე. გაიმეორე და სცადე კიდევ.','You need 80% without hints. Review and try again.','Нужно 80% без подсказок. Повтори и попробуй ещё.')}</p>${button(q.kind,tr('მოდულებზე დაბრუნება','Back to modules','К модулям'))}${footer()}</div>`,'result');if(passed)celebrate();}
 function conversations(){conversation=null;show(`<h2>${tr('ყოველდღიური საუბრები 💬','Everyday conversations 💬','Повседневные диалоги 💬')}</h2><p class="sub">${tr('აირჩიე სიტუაცია. მოუსმინე თითოეულ რეპლიკას, ნახე თარგმანი და როლებით ივარჯიშე.','Choose a situation. Listen to each line, reveal translations and practise by role.','Выбери ситуацию. Слушай реплики, смотри перевод и тренируйся по ролям.')}</p>${[...new Set(conversationBank.map(c=>c.category))].map(cat=>{const group=conversationBank.filter(c=>c.category===cat);return `<h3>${esc(label(group[0].categoryTitle))}</h3><div class="reading-list">${group.map(c=>`<button class="reading-link" data-v3="conversation-open" data-id="${c.id}"><span>${esc(label(c.title))}</span><small>${c.level} · ${c.turns.length} 💬</small></button>`).join('')}</div>`}).join('')}`,'library')}
 function openConversation(id){conversation=conversationBank.find(c=>c.id===id);if(!conversation)return;turn=0;drawConversation()}
 function drawConversation(){const c=conversation;if(!c)return;show(`${button('conversations','← '+tr('სიტუაციები','Situations','Ситуации'))}<div class="eyebrow">${esc(label(c.categoryTitle))} · ${c.level}</div><h2>${esc(label(c.title))}</h2><p class="hint">${tr('დააჭირე რეპლიკას მოსასმენად. თარგმანი იხსნება ცალკე.','Tap a line to listen. Reveal its translation separately.','Нажми на реплику, чтобы послушать. Перевод открывается отдельно.')}</p><div class="dialogue-thread">${c.turns.map((line,i)=>`<div class="dialogue-line ${i%2?'other':''}"><span class="dialogue-speaker">${esc(line.speaker)}</span><button data-audio="${esc(line[getCourse()])}" class="dialogue-audio" data-learning>${esc(line[getCourse()])} 🔊</button><details><summary>${tr('თარგმანი','Translation','Перевод')}</summary><p data-learning>${esc(line[getBase()])}</p></details></div>`).join('')}</div><button class="primary bank-launch" data-v4="bank-library" data-bank="${c.id+'-'+getCourse()}">${bankSize(c.id+'-'+getCourse())} ${tr('სავარჯიშო →','exercises →','заданий →')}</button><div class="roleplay"><h3>${tr('როლური თამაში','Role play','Ролевая практика')}</h3><p id="role-line" data-learning>${esc(c.turns[turn][getCourse()])}</p>${button('role-next',tr('შემდეგი რეპლიკა →','Next line →','Следующая реплика →'))}<p class="hint">${tr('მოუსმინე, შემდეგ უპასუხე შენი ხმით.','Listen, then reply out loud.','Послушай, затем ответь вслух.')}</p></div>`,'conversation')}
 function click(b){const a=b.dataset.v3;if(!a)return false;playTicket++;
 if(a==='listen'||a==='grammar')library(a);if(a==='listen-level'||a==='grammar-level'){stage=b.dataset.stage;library(a.split('-')[0])}if(a==='listen-open')listening(b.dataset.id);if(a==='grammar-open')grammar(b.dataset.id);if(a==='grammar-quiz'){quiz={kind:'grammar',module:grammarBank[getCourse()].find(m=>m.id===b.dataset.id),index:0,answers:[],hints:[],checked:false};drawQuiz()}
 if(a==='grammar-answer'&&quiz&&!quiz.checked){quiz.selected=quiz.module.quiz[quiz.index].options[Number(b.dataset.index)];document.querySelectorAll('[data-v3="grammar-answer"]').forEach(el=>el.classList.toggle('chosen',el===b))}
 if(a==='quiz-check')checkQuiz();if(a==='quiz-next'){quiz.index++;quiz.selected='';drawQuiz()}if(a==='listen-hint'&&quiz)quiz.hinted=true;if(a==='slow'&&quiz)speak(quiz.module.items[quiz.index][getCourse()],true);
 if(a==='conversations')conversations();if(a==='conversation-open')openConversation(b.dataset.id);if(a==='role-next'&&conversation){turn=(turn+1)%conversation.turns.length;document.querySelector('#role-line').textContent=conversation.turns[turn][getCourse()];speak(conversation.turns[turn][getCourse()])}
return true;}
 return {click,library,conversations,input(){},keydown(e){if(e.key==='Enter'&&e.target.id==='hub-answer'){e.preventDefault();if(quiz?.checked){quiz.index++;drawQuiz()}else checkQuiz()}}};
}
